CREATE OR REPLACE PROCEDURE sp(para_Num_of_Pieces integer, para_Performance_ID integer, para_Attendance integer, para_integer text) LANGUAGE plpgsql AS $$ DECLARE cur CURSOR FOR SELECT "Attendance", "integer" FROM "performance" WHERE "Attendance" > para_Attendance; rec RECORD; att RECORD; var1 integer; var2 text; v_attendance integer; v_integer text; BEGIN var1 := para_Num_of_Pieces * 2; var2 := para_Performance_ID::text; IF para_Num_of_Pieces < 10 THEN FOR rec IN SELECT ctid AS row_id, "Num_of_Pieces" FROM "member_attendance" LOOP IF rec."Num_of_Pieces" < var1 THEN UPDATE "member_attendance" SET "Num_of_Pieces" = "Num_of_Pieces" + para_Performance_ID WHERE ctid = rec.row_id; END IF; END LOOP; FOR rec IN SELECT ctid AS row_id, "Attendance", "integer" FROM "performance" LOOP IF rec."Attendance" = para_Attendance AND rec."integer" LIKE var2 THEN DELETE FROM "performance" WHERE ctid = rec.row_id; END IF; END LOOP; FOR rec IN SELECT ctid AS row_id, "Attendance" FROM "performance" LOOP IF rec."Attendance" = para_Attendance THEN UPDATE "performance" SET "Location" = CONCAT("Location", ':', var2) WHERE ctid = rec.row_id; END IF; END LOOP; FOR rec IN SELECT ctid AS row_id, "Attendance" FROM "performance" LOOP IF rec."Attendance" >= var1 THEN UPDATE "performance" SET "Host" = CONCAT("Host", ':', var2) WHERE ctid = rec.row_id; END IF; END LOOP; ELSIF para_Num_of_Pieces < 20 THEN OPEN cur; LOOP FETCH cur INTO rec; EXIT WHEN NOT FOUND; v_attendance := rec."Attendance"; v_integer := rec."integer"; FOR att IN SELECT ctid AS row_id FROM "member_attendance" WHERE "Num_of_Pieces" = v_attendance LOOP UPDATE "member_attendance" SET "Performance_ID" = v_integer WHERE ctid = att.row_id; END LOOP; var1 := var1 + 1; END LOOP; CLOSE cur; ELSIF para_Num_of_Pieces < 30 THEN FOR rec IN SELECT ctid AS row_id, "Attendance" FROM "performance" LOOP IF rec."Attendance" < para_Attendance THEN UPDATE "performance" SET "integer" = var2 WHERE ctid = rec.row_id; END IF; END LOOP; FOR rec IN SELECT ctid AS row_id FROM "member_attendance" LOOP
 -- <<< region omitted from the export >>>
 END LOOP; FOR rec IN SELECT ctid AS row_id, "Attendance" FROM "performance" LOOP IF rec."Attendance" % 5 = 0 THEN DELETE FROM "performance" WHERE ctid = rec.row_id; END IF; END LOOP; ELSIF para_Num_of_Pieces < 40 THEN FOR rec IN SELECT ctid AS row_id FROM "member_attendance" LOOP IF para_Performance_ID > 50 THEN UPDATE "member_attendance" SET "Num_of_Pieces" = "Num_of_Pieces" / 2 WHERE ctid = rec.row_id; ELSE UPDATE "member_attendance" SET "Num_of_Pieces" = "Num_of_Pieces" * 3 WHERE ctid = rec.row_id; END IF; END LOOP; FOR rec IN SELECT ctid AS row_id, "integer" FROM "performance" LOOP IF rec."integer" IS NULL THEN DELETE FROM "performance" WHERE ctid = rec.row_id; END IF; END LOOP; INSERT INTO "performance" ("Attendance", "integer") VALUES (var1, 'fallback'); ELSE INSERT INTO "performance" ("Attendance", "integer") VALUES (para_Attendance, para_integer); FOR rec IN SELECT ctid AS row_id, "Num_of_Pieces" FROM "member_attendance" LOOP IF rec."Num_of_Pieces" > 100 THEN UPDATE "member_attendance" SET "Performance_ID" = 'final_state' WHERE ctid = rec.row_id; END IF; END LOOP; END IF; END; $$;
